1062	async function runCompare(oldArg: string, newArg: string): Promise<never> {
1063	  const oldFile = path.resolve(oldArg);
1064	  const newFile = path.resolve(newArg);
1065	
1066	  const attempt = async (
1067	    file: string,
1068	  ): Promise<{ specs?: EndpointSpec[]; error?: string }> => {
1069	    try {
1070	      return { specs: await loadSpecsFromFile(file) };
1071	    } catch (e) {
1072	      return { error: describeError(e) };
1073	    }
1074	  };
1075	
1076	  // 两份文件都完整经历 读取 -> 解析 -> 严格校验；任一失败则不输出任何报告
1077	  const [oldResult, newResult] = await Promise.all([attempt(oldFile), attempt(newFile)]);
1078	  let failed = false;
1079	  if (oldResult.error !== undefined) {
1080	    process.stderr.write(`${APP_NAME}: compare 旧文件：${oldResult.error}\n`);
1081	    failed = true;
1082	  }
1083	  if (newResult.error !== undefined) {
1084	    process.stderr.write(`${APP_NAME}: compare 新文件：${newResult.error}\n`);
1085	    failed = true;
1086	  }
1087	  if (failed) {
1088	    process.exit(2);
1089	  }
1090	
1091	  const report = compareConfigs(
1092	    oldResult.specs as EndpointSpec[],
1093	    newResult.specs as EndpointSpec[],
1094	    oldFile,
1095	    newFile,
1096	  );
1097	  process.stdout.write(`${JSON.stringify(report, null, 2)}\n`);
1098	  process.exit(report.compatible ? 0 : 1);
1099	}
