1234	// 解析一层 $ref：node 是“只含 $ref 的引用节点”时返回目标与新的位置/引用链，
1235	// 否则返回 null。外部引用、非法指针、目标缺失、循环引用都在此拒绝。
1236	function dereference(
1237	  node: Record<string, unknown>,
1238	  ctx: ImportCtx,
1239	  where: string,
1240	  refChain: readonly string[],
1241	): { target: unknown; where: string; refChain: readonly string[] } | null {
1242	  if (!hasOwnKey(node, '$ref')) {
1243	    return null;
1244	  }
1245	  if (Object.keys(node).length !== 1) {
1246	    importFail(ctx, where, '含 $ref 的引用节点不得包含其他字段（只允许 "$ref"）');
1247	  }
1248	  const ref = node.$ref;
1249	  if (typeof ref !== 'string' || !ref.startsWith('#')) {
1250	    importFail(
1251	      ctx,
1252	      where,
1253	      `仅支持本文件内 $ref（以 "#" 开头的 JSON Pointer），收到 ${JSON.stringify(ref)}`,
1254	    );
1255	  }
1256	  if (refChain.includes(ref as string)) {
1257	    importFail(ctx, where, `循环 $ref 引用：${[...refChain, ref].join(' -> ')}`);
1258	  }
1259	  const fragment = (ref as string).slice(1);
1260	  let target: unknown = ctx.doc;
1261	  if (fragment !== '') {
1262	    if (!fragment.startsWith('/')) {
1263	      importFail(ctx, where, `$ref "${ref as string}" 不是合法的 JSON Pointer 片段`);
1264	    }
1265	    const segments = fragment
1266	      .slice(1)
1267	      .split('/')
1268	      .map((seg) => unescapeRefSegment(seg, ref as string, ctx, where));
1269	    let traversed = '#';
1270	    for (const segment of segments) {
1271	      traversed = `${traversed}/${escapePointerSegment(segment)}`;
1272	      if (Array.isArray(target)) {
1273	        if (!/^(0|[1-9]\d*)$/.test(segment) || Number(segment) >= target.length) {
1274	          importFail(ctx, where, `$ref "${ref as string}" 的目标不存在：${traversed} 超出数组范围`);
1275	        }
1276	        target = target[Number(segment)];
1277	      } else if (isPlainObject(target)) {
1278	        if (!hasOwnKey(target, segment)) {
1279	          importFail(ctx, where, `$ref "${ref as string}" 的目标不存在：${traversed} 缺失`);
1280	        }
1281	        target = target[segment];
1282	      } else {
1283	        importFail(ctx, where, `$ref "${ref as string}" 无法继续解析：${traversed} 不是对象或数组`);
1284	      }
1285	    }
1286	  }
1287	  return { target, where: `${where} -> ${ref as string}`, refChain: [...refChain, ref as string] };
1288	}
