1322	// 组合节点键校验（仅 allOf 与注释）并取出非空 allOf 数组
1323	function comboList(n: Record<string, unknown>, ctx: ImportCtx, nodeWhere: string): unknown[] {
1324	  for (const key of Object.keys(n)) {
1325	    if (key !== 'allOf' && !OPENAPI_ANNOTATION_KEYS.has(key)) {
1326	      importFail(
1327	        ctx,
1328	        nodeWhere,
1329	        `组合节点仅允许 allOf 及注释（title/description/example/nullable），含未支持的关键字 "${key}"`,
1330	      );
1331	    }
1332	  }
1333	  const list = n.allOf;
1334	  if (!Array.isArray(list) || list.length === 0) {
1335	    importFail(ctx, `${nodeWhere}.allOf`, '必须是非空数组');
1336	  }
1337	  return list as unknown[];
1338	}
1339	
1340	// 递归收集（可能嵌套的）allOf 子树的全部对象叶分支：组合节点只含 allOf 与
1341	// 注释，其子树展开后的叶分支即全部参与交集的分支。交集满足结合律，故展平不
1342	// 改变接受集合，也使成功/拒绝结论与分支顺序、嵌套分组无关。loc 保留每个叶分
1343	// 支的精确位置（含嵌套 allOf 下标与 $ref 链），用于来源定位。
1344	interface ObjectLeaf {
1345	  readonly rule: NormObject;
1346	  readonly loc: string;
1347	}
1348	
1349	function collectObjectLeaves(
1350	  list: readonly unknown[],
1351	  ctx: ImportCtx,
1352	  parentWhere: string,
1353	  chain: readonly string[],
1354	): ObjectLeaf[] {
1355	  const leaves: ObjectLeaf[] = [];
1356	  list.forEach((raw, i) => {
1357	    const branchWhere = `${parentWhere}.allOf[${i}]`;
1358	    const { n, nodeWhere, chain: ch } = resolveSchemaNode(raw, ctx, branchWhere, chain);
1359	    if (hasOwnKey(n, 'allOf')) {
1360	      leaves.push(...collectObjectLeaves(comboList(n, ctx, nodeWhere), ctx, nodeWhere, ch));
1361	      return;
1362	    }
1363	    const rule = buildSimpleNorm(n, ctx, nodeWhere, ch);
1364	    if (rule.kind !== 'object') {
1365	      importFail(ctx, nodeWhere, `仅支持纯对象 allOf 组合，该分支最终类型为 ${rule.kind}`);
1366	    }
1367	    leaves.push({ rule: rule as NormObject, loc: nodeWhere });
1368	  });
1369	  return leaves;
1370	}
1371	
1372	// schema（或引用链尽头的 schema）-> 规范化规则
1373	function schemaToNorm(
1374	  rawNode: unknown,
1375	  ctx: ImportCtx,
1376	  where: string,
1377	  refChain: readonly string[],
1378	): NormRule {
1379	  const { n, nodeWhere, chain } = resolveSchemaNode(rawNode, ctx, where, refChain);
1380	
1381	  if (hasOwnKey(n, 'allOf')) {
1382	    const leaves = collectObjectLeaves(comboList(n, ctx, nodeWhere), ctx, nodeWhere, chain);
1383	    const result = intersectObjects(
1384	      leaves.map((l) => ({ rule: l.rule, loc: l.loc })),
1385	      nodeWhere,
1386	    );
1387	    // 整体空交集 与 非空但无法表达 都拒绝；reason 含冲突字段/元素与失败理由，
1388	    // loc 指向贡献该结论的叶分支（可定位的操作或定义位置）
1389	    if (result.tag === 'empty' || result.tag === 'inexpressible') {
1390	      importFail(ctx, result.loc, result.reason);
1391	    }
1392	    return result.rule;
1393	  }
1394	
1395	  return buildSimpleNorm(n, ctx, nodeWhere, chain);
1396	}
1397	
1398	// 非组合（非 allOf）schema -> 规范化规则
1399	function buildSimpleNorm(
1400	  n: Record<string, unknown>,
1401	  ctx: ImportCtx,
1402	  nodeWhere: string,
1403	  chain: readonly string[],
1404	): NormRule {
1405	  const type = n.type;
1406	  if (
1407	    typeof type !== 'string' ||
1408	    (type !== 'object' && type !== 'array' && !OPENAPI_SCALAR_TYPES.has(type))
1409	  ) {
1410	    importFail(
1411	      ctx,
1412	      `${nodeWhere}.type`,
1413	      `必须是 "object" | "array" | "string" | "number" | "integer" | "boolean"，收到 ${JSON.stringify(n.type)}`,
1414	    );
1415	  }
1416	  const structural: readonly string[] =
1417	    type === 'object'
1418	      ? ['properties', 'required', 'additionalProperties']
1419	      : type === 'array'
1420	        ? ['items']
1421	        : [];
1422	  for (const key of Object.keys(n)) {
1423	    if (key !== 'type' && !OPENAPI_ANNOTATION_KEYS.has(key) && !structural.includes(key)) {
1424	      importFail(ctx, nodeWhere, `含未支持的关键字 "${key}"`);
1425	    }
1426	  }
1427	
1428	  if (type === 'array') {
1429	    if (!hasOwnKey(n, 'items')) {
1430	      importFail(ctx, `${nodeWhere}.items`, '数组 schema 必须声明元素规则 items');
1431	    }
1432	    return { kind: 'array', items: schemaToNorm(n.items, ctx, `${nodeWhere}.items`, chain) };
1433	  }
1434	
1435	  if (type === 'object') {
1436	    const propsRaw = n.properties;
1437	    if (propsRaw !== undefined && !isPlainObject(propsRaw)) {
1438	      importFail(ctx, `${nodeWhere}.properties`, '必须是对象（字段名 -> schema）');
1439	    }
1440	    const reqRaw = n.required;
1441	    const requiredList: string[] = [];
1442	    if (reqRaw !== undefined) {
1443	      if (!Array.isArray(reqRaw)) {
1444	        importFail(ctx, `${nodeWhere}.required`, '必须是字符串数组');
1445	      }
1446	      for (let i = 0; i < (reqRaw as unknown[]).length; i += 1) {
1447	        const item = (reqRaw as unknown[])[i];
1448	        if (typeof item !== 'string') {
1449	          importFail(ctx, `${nodeWhere}.required[${i}]`, `必须是字符串，收到 ${JSON.stringify(item)}`);
1450	        }
1451	        if (requiredList.includes(item as string)) {
1452	          importFail(ctx, `${nodeWhere}.required`, `含重复项 ${JSON.stringify(item)}`);
1453	        }
1454	        requiredList.push(item as string);
1455	      }
1456	    }
1457	    const props = new Map<string, NormRule>();
1458	    if (propsRaw !== undefined) {
1459	      for (const [name, sub] of Object.entries(propsRaw as Record<string, unknown>)) {
1460	        props.set(
1461	          name,
1462	          schemaToNorm(sub, ctx, `${nodeWhere}.properties[${JSON.stringify(name)}]`, chain),
1463	        );
1464	      }
1465	    }
1466	    for (const name of requiredList) {
1467	      if (!props.has(name)) {
1468	        importFail(ctx, `${nodeWhere}.required`, `${JSON.stringify(name)} 未在同层 properties 中声明`);
1469	      }
1470	    }
1471	    const addlRaw = n.additionalProperties;
1472	    if (addlRaw !== undefined && typeof addlRaw !== 'boolean') {
1473	      importFail(
1474	        ctx,
1475	        `${nodeWhere}.additionalProperties`,
1476	        `仅支持布尔值，收到 ${JSON.stringify(addlRaw)}`,
1477	      );
1478	    }
1479	    // OpenAPI 缺省允许未声明字段；输出时显式写出
1480	    return { kind: 'object', props, required: new Set(requiredList), addl: addlRaw !== false };
1481	  }
1482	
1483	  return { kind: type as 'string' | 'number' | 'integer' | 'boolean' };
1484	}
1485	
1486	// 标量类型交集：相同类型取自身；number ∩ integer 取 integer；其余组合为空。
1487	// 结果与顺序无关。
1488	function scalarIntersection(
1489	  a: NormRule,
1490	  b: NormRule,
1491	): { kind: 'string' | 'number' | 'integer' | 'boolean' } | null {
1492	  if (a.kind === b.kind) {
1493	    return a as { kind: 'string' | 'number' | 'integer' | 'boolean' };
1494	  }
1495	  if (
1496	    (a.kind === 'number' && b.kind === 'integer') ||
1497	    (a.kind === 'integer' && b.kind === 'number')
1498	  ) {
1499	    return { kind: 'integer' };
1500	  }
1501	  return null;
1502	}
1503	
1504	// 参与交集的一个规则分支：rule 是其规范化规则，loc 是该规则在文档中的精确
1505	// 来源位置（对象取 allOf 叶分支位置、字段取 ...properties["名"]、元素取 ...items），
1506	// 用于在拒绝时给出可定位的操作或定义位置。
1507	interface RuleBranch {
1508	  readonly rule: NormRule;
1509	  readonly loc: string;
1510	}
1511	
1512	// 多个对象分支（可能来自嵌套 allOf）接受集合的交集。
1513	// 必须对“全部分支同时”判定，结论与分支顺序、嵌套分组无关；不可在两两折叠的
1514	// 中途因某个中间交集不可表达就拒绝——再叠加分支后真实交集可能变为可表达
1515	// （例如 string 与 integer 两支本不可表达，第三支是封闭空对象后，交集恰为
1516	// 只接受空对象的封闭对象）。
1517	function intersectObjects(flat: readonly RuleBranch[], where: string): Intersection {
1518	  const objs = flat.map((b) => b.rule as NormObject);
1519	  // 结果的 additionalProperties 为各分支的合取（任一分支拒绝则拒绝）
1520	  const addl = objs.every((o) => o.addl);
1521	
1522	  const names: string[] = [];
1523	  const seen = new Set<string>();
1524	  for (const o of objs) {
1525	    for (const name of o.props.keys()) {
1526	      if (!seen.has(name)) {
1527	        seen.add(name);
1528	        names.push(name);
1529	      }
1530	    }
1531	  }
1532	
1533	  const props = new Map<string, NormRule>();
1534	  const required = new Set<string>();
1535	  // 非空但无法表达时的首个原因与位置（可能随后被收窄为空交集）
1536	  let inex: { reason: string; loc: string } | undefined;
1537	
1538	  const noteInexpressible = (reason: string, loc: string): void => {
1539	    if (inex === undefined) {
1540	      inex = { reason, loc };
1541	    }
1542	  };
1543	
1544	  for (const name of names) {
1545	    const isRequired = objs.some((o) => o.required.has(name));
1546	
1547	    // 真正约束该字段取值的声明分支（附精确来源位置）；以及首个禁止它出现的分支
1548	    // （未声明且该分支 additionalProperties 为 false）
1549	    const declarers: RuleBranch[] = [];
1550	    let forbiddener: RuleBranch | undefined;
1551	    for (let i = 0; i < flat.length; i += 1) {
1552	      const o = objs[i];
1553	      const sub = o.props.get(name);
1554	      if (sub !== undefined) {
1555	        declarers.push({ rule: sub, loc: `${flat[i].loc}.properties[${JSON.stringify(name)}]` });
1556	      } else if (!o.addl && forbiddener === undefined) {
1557	        forbiddener = flat[i];
1558	      }
1559	    }
1560	
1561	    if (forbiddener !== undefined) {
1562	      if (isRequired) {
1563	        return {
1564	          tag: 'empty',
1565	          reason:
1566	            `字段 ${JSON.stringify(name)} 在部分分支中为必填，但被另一分支禁止出现` +
1567	            '（未声明且 additionalProperties 为 false），交集为空',
1568	          loc: forbiddener.loc,
1569	        };
1570	      }
1571	      // 可选且被禁止：结果中不声明该字段即“禁止出现”。其余声明分支的取值交集
1572	      // 为何都无关紧要——该字段根本不能出现（声明分支中的非法 schema 仍在
1573	      // schemaToNorm 阶段被拒绝，不会走到这里）。
1574	      continue;
1575	    }
1576	
1577	    // 没有任何分支声明它：各分支仅以“允许额外字段”放行，交集对它无约束
1578	    if (declarers.length === 0) {
1579	      continue;
1580	    }
1581	
1582	    const sub = intersectRules(declarers, `${where}.properties[${JSON.stringify(name)}]`);
1583	
1584	    if (sub.tag === 'empty') {
1585	      if (isRequired) {
1586	        return {
1587	          tag: 'empty',
1588	          reason: `必填字段 ${JSON.stringify(name)} 的各分支规则交集为空：${sub.reason}`,
1589	          loc: sub.loc,
1590	        };
1591	      }
1592	      if (!addl) {
1593	        // 可选字段交集为空、结果又拒绝额外字段：不声明即“禁止出现”，可表达
1594	        continue;
1595	      }
1596	      // 所有分支都允许额外字段时，无法表达“仅该字段禁止出现、其他字段任意”
1597	      noteInexpressible(
1598	        `可选字段 ${JSON.stringify(name)} 的各分支规则交集为空（${sub.reason}），` +
1599	          '且所有分支都允许额外字段，现有规则种类无法表达“仅禁止该字段出现”',
1600	        sub.loc,
1601	      );
1602	      continue;
1603	    }
1604	
1605	    if (sub.tag === 'inexpressible') {
1606	      // 子级非空但不可表达：本字段可选时外层封闭也许能补救，故带近似规则继续，
1607	      // 先记录原因；必填字段的不可表达在外层封闭也无法补救，最终仍会拒绝。
1608	      noteInexpressible(
1609	        `${isRequired ? '必填' : '可选'}字段 ${JSON.stringify(name)} 的各分支规则交集非空但无法表达：${sub.reason}`,
1610	        sub.loc,
1611	      );
1612	      props.set(name, sub.rule);
1613	      if (isRequired) {
1614	        required.add(name);
1615	      }
1616	      continue;
1617	    }
1618	
1619	    props.set(name, sub.rule);
1620	    if (isRequired) {
1621	      required.add(name);
1622	    }
1623	  }
1624	
1625	  const merged: NormObject = { kind: 'object', props, required, addl };
1626	  if (inex !== undefined) {
1627	    return { tag: 'inexpressible', rule: merged, reason: inex.reason, loc: inex.loc };
1628	  }
1629	  return { tag: 'nonempty', rule: merged };
1630	}
