1871	async function runImport(openapiArg: string, configArg: string): Promise<never> {
1872	  const openapiFile = path.resolve(openapiArg);
1873	  const configFile = path.resolve(configArg);
1874	  try {
1875	    const sceneRaw = await readImportInput(configFile, '场景配置文件');
1876	    try {
1877	      validateConfig(sceneRaw);
1878	    } catch (e) {
1879	      throw new ImportError(`场景配置文件 ${configFile} 校验失败：${describeError(e)}`);
1880	    }
1881	    const doc = await readImportInput(openapiFile, 'OpenAPI 文件');
1882	    const endpoints = importEndpoints(sceneRaw, { doc, file: openapiFile });
1883	    // 全部输入与所选可达定义有效后才输出
1884	    process.stdout.write(`${JSON.stringify({ endpoints }, null, 2)}\n`);
1885	    process.exit(0);
1886	  } catch (e) {
1887	    process.stderr.write(`${APP_NAME}: import：${describeError(e)}\n`);
1888	    process.exit(2);
