1896	// 模块级运行时句柄（启动后赋值）
1897	let activeState: LiveState;
1898	let server: http.Server;
1899	let configFile = '';
1900	let shuttingDown = false;
1901	
1902	// 进程内请求记录：与配置版本、序列相互独立，reload 与清空都不影响编号单调
1903	const requestLog = new RequestLog();
1904	
1905	// 尚未发出的延迟响应定时器，关闭时统一取消
1906	const pendingTimers = new Set<ReturnType<typeof setTimeout>>();
1907	
1908	// 重载按“触发顺序”串行处理：后一个 reload 必定在前一个落定后才读文件
1909	let reloadChain: Promise<unknown> = Promise.resolve();
1910	
1911	function triggerReload(): Promise<ReloadResult> {
1912	  const job = reloadChain.then(async (): Promise<ReloadResult> => {
1913	    try {
1914	      // 校验通过前只构造局部变量，任何失败都不会触碰 activeState
1915	      const next = await loadStateFromFile(configFile, activeState.version + 1);
1916	      activeState = next; // 单次同步赋值：请求不可能看到混合配置
1917	      return { ok: true, version: activeState.version };
1918	    } catch (e) {
1919	      // 不修改配置/版本，不重置序列；旧场景的正常消费继续
1920	      return { ok: false, version: activeState.version, error: describeError(e) };
1921	    }
1922	  });
1923	  // 失败也不能打断后续 reload 的排队
1924	  reloadChain = job.then(
1925	    () => undefined,
1926	    () => undefined,
1927	  );
1928	  return job;
1929	}
