1931	function writeResponse(
1932	  res: http.ServerResponse,
1933	  status: number,
1934	  headers: { readonly [name: string]: string },
1935	  body: string,
1936	): void {
1937	  try {
1938	    res.writeHead(status, headers);
1939	    res.end(body === '' ? undefined : body);
1940	  } catch {
1941	    // 预留之后客户端可能已断开：响应仍计为已消费，发送失败仅静默忽略
1942	  }
1943	}
