1971	    res,
1972	    404,
1973	    versionHeaders(activeState.version, {
1974	      'Content-Type': 'text/plain; charset=utf-8',
1975	    }),
1976	    'not found\n',
1977	  );
1978	}
1979	
1980	// ---------------------------------------------------------------------------
1981	// 计划响应快照与写出跟踪
1982	// ---------------------------------------------------------------------------
1983	//
1984	// 业务/框架响应在“请求完整接收”那一刻就构造为一份计划快照：
1985	// 记录中保存的状态/应用层头/正文与随后真正写上线的字节共用同一份数据，
1986	// reload 不影响在途请求（它持有的是快照而非当前配置）。
1987	
1988	function freezeHeaders(headers: { [name: string]: string }): { readonly [name: string]: string } {
1989	  return Object.freeze(headers);
1990	}
1991	
1992	// 场景响应的应用层头：配置头 + 服务器填写的准确版本头（+ 必要时的默认 Content-Type）。
1993	// 不含 Content-Length/Connection/Date/Transfer-Encoding 等传输层自动头。
1994	function buildSceneHeaders(
1995	  item: ResponseSpec,
1996	  version: number,
1997	): { readonly [name: string]: string } {
1998	  const headers = versionHeaders(version);
1999	  let contentTypeSet = false;
2000	  for (const [name, value] of Object.entries(item.headers)) {
2001	    const lower = name.toLowerCase();
2002	    // 版本头由服务器填写且必须唯一准确：配置中的同名头（含大小写变体）可加载，发送时忽略其值
2003	    if (lower === VERSION_HEADER.toLowerCase()) {
2004	      continue;
2005	    }
2006	    if (lower === 'content-type') {
2007	      contentTypeSet = true;
2008	    }
2009	    headers[name] = value;
2010	  }
2011	  // 文本正文的默认内容类型；配置显式给出时不覆盖
2012	  if (!contentTypeSet && item.body !== '') {
2013	    headers['Content-Type'] = 'text/plain; charset=utf-8';
2014	  }
2015	  return freezeHeaders(headers);
2016	}
2017	
2018	function buildScenePlanned(item: ResponseSpec, version: number): PlannedResponseSnapshot {
2019	  return {
2020	    kind: 'scene',
2021	    status: item.status,
2022	    headers: buildSceneHeaders(item, version),
2023	    body: item.body,
2024	  };
2025	}
2026	
2027	function buildFrameworkPlanned(
2028	  status: number,
2029	  version: number,
2030	  body: string,
2031	  contentType: string,
2032	): PlannedResponseSnapshot {
2033	  return {
2034	    kind: 'framework',
2035	    status,
2036	    headers: freezeHeaders(versionHeaders(version, { 'Content-Type': contentType })),
2037	    body,
2038	  };
2039	}
2040	
2041	// 按计划快照写出；writeHead/end 在已断开套接字上抛错时标记为中断（消费已成立）。
2042	function writePlanned(
2043	  res: http.ServerResponse,
2044	  planned: PlannedResponseSnapshot,
2045	  recordId: number,
2046	): void {
2047	  try {
2048	    res.writeHead(planned.status, { ...planned.headers });
2049	    res.end(planned.body === '' ? undefined : planned.body);
2050	  } catch {
2051	    requestLog.markDelivered(recordId, 'interrupted');
2052	  }
2053	}
2054	
2055	// 挂载一次写出生命周期跟踪。每个被记录的请求恰好回复一次，故在接收完成后立即挂载：

