210	function isPlainJsonObject(value: unknown): value is Record<string, unknown> {
211	  return typeof value === 'object' && value !== null && !Array.isArray(value);
212	}
213	
214	export function accepts(rule: RuleJson, value: unknown): boolean {
215	  switch (rule.type) {
216	    case 'string':
217	      return typeof value === 'string';
218	    case 'boolean':
219	      return typeof value === 'boolean';
220	    case 'null':
221	      return value === null;
