```ts
function rawExchange(port: number, raw: Buffer): Promise<number> {
  return new Promise((resolve, reject) => {
    const socket = net.connect(port, '127.0.0.1', () => socket.write(raw));
    let head = '';
    socket.on('data', (c) => {
      if (!head.includes('\r\n')) {
        head += c.toString('latin1');
        const m = head.match(/^HTTP\/1\.\d (\d{3})/);
        if (m) { resolve(Number(m[1])); socket.resume(); }
      }
    });
    socket.on('error', reject);
    setTimeout(() => reject(new Error('rawExchange 超时')), 10_000).unref();
  });
}
```

