93	  method: string,
94	  target: string,
95	  headers: readonly [string, string][],
96	  body: Buffer,
97	): Buffer {
98	  const lines = [`${method} ${target} HTTP/1.1`, 'Host: 127.0.0.1'];
99	  for (const [name, value] of headers) {
