116	function rawExchange(port: number, raw: Buffer): Promise<number> {
117	  return new Promise((resolve, reject) => {
118	    const socket = net.connect(port, '127.0.0.1', () => socket.write(raw));
119	    const chunks: Buffer[] = [];
120	    socket.on('data', (c: Buffer) => chunks.push(c));
121	    socket.on('end', () => {
122	      const head = Buffer.concat(chunks).toString('latin1');
123	      const m = head.match(/^HTTP\/1\.\d (\d{3})/);
124	      if (m) {
125	        resolve(Number(m[1]));
126	      } else {
127	        reject(new Error(`未收到完整响应状态行：${head.slice(0, 120)}`));
128	      }
129	    });
130	    socket.on('error', reject);
131	    socket.setTimeout(10_000, () => {
132	      socket.destroy();
133	      reject(new Error('原始请求 10s 内未完成（疑似卡住）'));
134	    });
135	  });
136	}
