138	function httpGetBody(port: number, path: string): Promise<string> {
139	  return new Promise((resolve, reject) => {
140	    const r = http.get({ host: '127.0.0.1', port, path }, (res) => {
141	      let data = '';
142	      res.setEncoding('utf8');
143	      res.on('data', (d: string) => (data += d));
144	      res.on('end', () => resolve(data));
145	    });
146	    r.on('error', reject);
147	    r.setTimeout(10_000, () => r.destroy(new Error(`GET ${path} 超时`)));
